<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Agency extends Model { protected $guarded=[]; protected $casts=['license_expires_at'=>'date','trial_ends_at'=>'datetime','is_verified'=>'boolean','is_active'=>'boolean','languages'=>'array','marketplace_enabled'=>'boolean','marketplace_show_phone'=>'boolean','marketplace_show_whatsapp'=>'boolean','marketplace_show_address'=>'boolean','marketplace_show_license'=>'boolean','marketplace_show_exact_location'=>'boolean','marketplace_featured'=>'boolean','marketplace_featured_until'=>'datetime','profile_completed_at'=>'datetime']; public function users(){return $this->hasMany(User::class);} public function properties(){return $this->hasMany(Property::class);} public function province(){return $this->belongsTo(Province::class);} public function district(){return $this->belongsTo(District::class);} public function area(){return $this->belongsTo(Area::class);} public function plan(){return $this->belongsTo(Plan::class);} public function subscriptions(){return $this->hasMany(Subscription::class);} public function activeSubscription(){return $this->hasOne(Subscription::class)->where('status','active')->latestOfMany();} public function getRouteKeyName(){return 'slug';} }
